validator:
function validate(input) {
  const [{ Employee = [] }] = input;
  const seen = new Set();
  for (const [id, month, salary] of Employee) {
    if (id === null || month === null) return 'Every row needs an id and a month.';
    if (month < 1 || month > 12) return `Month ${month} is outside 1..12.`;
    if (salary === null || salary < 0) return `Employee ${id} needs a non-negative salary in month ${month}.`;
    const key = `${id}|${month}`;
    if (seen.has(key)) return `Employee ${id} has two rows for month ${month}.`;
    seen.add(key);
  }
  return null;
}

generator:
function generate(rand, size) {
  const small = size === 'small';
  const people = small ? 1 + Math.floor(rand() * 3) : 180;
  const Employee = [];
  for (let id = 1; id <= people; id++) {
    // Each employee works a random subset of months, often with gaps.
    const chance = small ? 0.15 + rand() * 0.4 : 0.3 + rand() * 0.7;
    for (let month = 1; month <= 12; month++) {
      if (small && Employee.length >= 8) break;
      if (rand() < chance) Employee.push([id, month, 10 * (1 + Math.floor(rand() * 9))]);
    }
  }
  // Shuffle so row order carries no information.
  for (let i = Employee.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [Employee[i], Employee[j]] = [Employee[j], Employee[i]]; }
  return [{ Employee }];
}
